    public async Task SourceGenerationDiagnosticsAreAlsoReportedWhenSuppressed()
    {
        // The partial-class requirement (MsgPack011) and the AOT check (MsgPack017)
        // are reported for a suppressed type just as for a source generated one.
        string input = Preamble + @"
[MessagePackObject(AllowPrivate = true, SuppressSourceGeneration = true)]
public class {|MsgPack011:Foo|}
{
    [Key(0)]
    private string member;

    [Key(1)]
    public string Prop1 { get; init; } {|MsgPack017:= ""some default""|};

    [Key(2)]
    public string Prop2 { get; set; }
}
";

        await new VerifyCS.Test
        {
            TestCode = input,
            MarkupOptions = MarkupOptions.UseFirstDescriptor,
        }.RunAsync();
    }
